const tabId = 1962625075;
const selects = await browserjs(tabId, () => {
  function getAllElements(root) {
    let list = Array.from(root.querySelectorAll('*'));
    for (const el of list) {
      if (el.shadowRoot) {
        list = list.concat(getAllElements(el.shadowRoot));
      }
    }
    return list;
  }
  const all = getAllElements(document);
  const selects = all.filter(e => e.tagName.toLowerCase() === 'select' || (e.getAttribute && (e.getAttribute('name')?.includes('sort') || e.getAttribute('id')?.includes('sort'))));
  return selects.map(s => ({
    tagName: s.tagName,
    id: s.id,
    name: s.name,
    options: Array.from(s.querySelectorAll('option')).map(o => ({ value: o.value, text: o.textContent.trim() }))
  }));
});
