const tabId = 1962625075;
const filterSections = await browserjs(tabId, () => {
  const lf = document.querySelector('listing-filters');
  const root = lf.shadowRoot || lf;

  // Click Body style button to expand it
  const bodyStyleBtn = Array.from(root.querySelectorAll('button')).find(b => b.textContent.includes('Body style'));
  if (bodyStyleBtn) bodyStyleBtn.click();

  // Click Interior color button
  const intColorBtn = Array.from(root.querySelectorAll('button')).find(b => b.textContent.includes('Interior color'));
  if (intColorBtn) intColorBtn.click();

  // Click Seating button
  const seatingBtn = Array.from(root.querySelectorAll('button')).find(b => b.textContent.includes('Seating'));
  if (seatingBtn) seatingBtn.click();

  // Click Entertainment button
  const entertainmentBtn = Array.from(root.querySelectorAll('button')).find(b => b.textContent.includes('Entertainment'));
  if (entertainmentBtn) entertainmentBtn.click();

  return {
    bodyStyle: !!bodyStyleBtn,
    intColor: !!intColorBtn,
    seating: !!seatingBtn,
    entertainment: !!entertainmentBtn
  };
});
console.log(JSON.stringify(filterSections, null, 2));

