const sortOptions = await browserjs(tabId, () => {
  const sortSelect = document.querySelector('select[name="sort"], #sort-dropdown, #sort, fuse-select[name="sort"]');
  if (sortSelect) {
    return Array.from(sortSelect.querySelectorAll('option')).map(o => ({ value: o.value, text: o.textContent.trim() }));
  }
  // Search for any select with sort
