const tabId = 1962625075;
const vehicleData = await browserjs(tabId, () => {
  // Let's find each vehicle listing container
  // Usually cars.com has vehicle-cards inside a list or grid
  const links = Array.from(document.querySelectorAll('a.vehicle-card-link, a[href*="/vehicledetail/"]'));

  // Deduplicate by href
  const seen = new Set();
  const results = [];

  for (const a of links) {
    const cleanHref = a.href.split('?')[0];
    if (seen.has(cleanHref)) continue;
    seen.add(cleanHref);

    // Find enclosing card
    let card = a;
    for (let i = 0; i < 6; i++) {
      if (!card.parentElement) break;
      card = card.parentElement;
      if (card.querySelector('.primary-price, [data-qa="primary-price"], .vehicle-card__price') || card.textContent.includes('$')) {
        break;
      }
    }

    results.push({
      title: a.textContent.trim(),
      href: cleanHref,
      text: card.textContent.replace(/\s+/g, ' ').trim()
    });
  }
  return results;
});

console.log(`Found ${vehicleData.length} unique vehicle links`);
for (let i = 0; i < Math.min(10, vehicleData.length); i++) {
  console.log(`--- Listing #${i+1} ---`);
  console.log("Title:", vehicleData[i].title);
  console.log("Href:", vehicleData[i].href);
  console.log("Text:", vehicleData[i].text.slice(0, 300));
}

