const tabId = 1962625075;
const vehicleDetails = await browserjs(tabId, () => {
  // Let's get title, price, basics, features, dealer info
  const title = document.querySelector('h1')?.textContent?.trim();
  const price = document.querySelector('.primary-price, [data-qa="primary-price"]')?.textContent?.trim();

  // Basics list / dl / table
  const basics = Array.from(document.querySelectorAll('dl, .fancy-description-list, .basics-section')).map(dl => dl.textContent.trim().replace(/\s+/g, ' '));

  // Features
  const features = Array.from(document.querySelectorAll('.features-section, .features-and-specs, [data-qa="features-section"], ul.features-list, .all-features-list')).map(f => f.textContent.trim().replace(/\s+/g, ' '));

  // Dealer info
  const dealer = Array.from(document.querySelectorAll('.dealer-name, .seller-details, .seller-info, [data-qa="seller-info"]')).map(d => d.textContent.trim().replace(/\s+/g, ' '));

  // Let's also look for text matches
  const pageText = document.body.innerText;

  return {
    title,
    price,
    basics,
    features,
    dealer,
    hasBlackInterior: pageText.toLowerCase().includes('black interior') || /interior\s*(?:color)?[\s:]*black/i.test(pageText),
    hasHeatedSeats: /heated\s*seat/i.test(pageText),
    hasPremiumSound: /premium\s*sound/i.test(pageText) || /audio/i.test(pageText) || /sound\s*system/i.test(pageText),
    pageTextSample: pageText.slice(0, 2000)
  };
});

